-- Payroll month-end lifecycle, freeze and payslips (SCRUM-569, the company
-- payroll's R4): docs/progress/plans/payroll-real-build/PLAN.md §1 and §9 R4.
--
-- Generated by drizzle-kit from shared/schema.ts and hand-edited as 0021-0024
-- are: re-runnable, the public-schema qualifier stripped, parent keys before
-- the foreign keys that use them. Expand-only. The run and run-version tables
-- and the draft's first inputs landed early in 0024 (R3); this migration holds
-- the rest of what the plan placed in 0025:
--
--   - payroll_run_overtime_decisions: Pay / Bank / Reject per overtime
--     occurrence of a fed attendance day, against the run version.
--   - payroll_run_third_party_approvals: a payment to someone else, approved
--     for the payment details it was approved with.
--   - payroll_run_audit: every run-input change and every transition (GM
--     confirm, Owner lock, paid, reopen). Append-only.
--   - payroll_run_snapshots: one per LOCKED version; everything the engine
--     read (world) and its result, calculation and outputs manifest.
--   - payroll_run_lines and payroll_output_files: written out from the
--     snapshot at lock (pay lines; payslips, bank files, cash list, reports).
--
-- Snapshots, lines and output files are unchangeable once written, and the
-- run audit is append-only: a trigger refuses UPDATE and DELETE on each.
-- Owner ruling 2026-10-20 (plan, open decision 3): company runs do not credit
-- the OT bank, so the plan's lock-time OT-bank ledger table is not created.
-- Nothing is seeded and no row is added to an older table.
CREATE TABLE IF NOT EXISTS "payroll_output_files" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"snapshot_id" uuid NOT NULL,
	"run_version_id" uuid NOT NULL,
	"employee_id" varchar,
	"file_group" text NOT NULL,
	"filename" text NOT NULL,
	"mime" text NOT NULL,
	"encoding" text NOT NULL,
	"content" text,
	"object_key" text,
	"sha256" text NOT NULL,
	"bytes" integer NOT NULL,
	"rows" integer NOT NULL,
	"total" numeric(14, 2) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payroll_output_files_encoding_check" CHECK ("payroll_output_files"."encoding" IN ('utf8', 'base64')),
	CONSTRAINT "payroll_output_files_body_check" CHECK ("payroll_output_files"."content" IS NOT NULL OR "payroll_output_files"."object_key" IS NOT NULL)
);
