-- Frozen payroll: a locked version's snapshot, lines and files never change,
-- and the run audit is append-only. Reopening writes a NEW version.
CREATE OR REPLACE FUNCTION payroll_frozen_rows() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
	RAISE EXCEPTION '% is frozen payroll: rows are never changed or removed (% refused)', TG_TABLE_NAME, TG_OP
		USING ERRCODE = 'restrict_violation';
END $fn$;
--> statement-breakpoint
DROP TRIGGER IF EXISTS payroll_run_snapshots_frozen ON "payroll_run_snapshots";
--> statement-breakpoint
CREATE TRIGGER payroll_run_snapshots_frozen
	BEFORE UPDATE OR DELETE ON "payroll_run_snapshots"
	FOR EACH ROW EXECUTE FUNCTION payroll_frozen_rows();
--> statement-breakpoint
